package validations

import (
	"kena.bot/api-db-go/internal/domain/dbguild"
)

// ModuleParams matches `paramsModuleValidation` (bot_id + guild_id).
// Used by every music/greeter/logs handler.
type ModuleParams struct {
	BotID   string `params:"bot_id"   validate:"required"`
	GuildID string `params:"guild_id" validate:"required"`
}

// ModuleMusicFieldParams adds the `:field` path segment. The field is
// constrained to the keys of `dbguild.ModuleMusic` at runtime by the
// handler — go-playground/validator cannot enforce "must be a key of this
// struct" without a custom tag, so the handler does the membership check
// after parsing.
type ModuleMusicFieldParams struct {
	BotID   string `params:"bot_id"   validate:"required"`
	GuildID string `params:"guild_id" validate:"required"`
	Field   string `params:"field"    validate:"required"`
}

// ModuleEnabledQuery matches `queryModuleEnabledValidation` in the
// Node service. `Module` is optional and, when present, must be one of
// the canonical module keys (`music | greeter | logs`). The
// go-playground `oneof` tag enforces the enum at bind time — unknown
// values produce a 400 Zod-shaped error.
//
// `tickets` is intentionally excluded from the `oneof` enum: the Node
// ModulesKeys array includes it, but the Node validator rejects it on
// the query param, and the controller has no implementation. The Go
// port mirrors that.
type ModuleEnabledQuery struct {
	Module string `query:"module" validate:"omitempty,oneof=music greeter logs"`
}

// UpdateModuleMusicBody mirrors the Node `updateModuleMusicSchema` (which
// is `moduleMusicSchema.partial()`). All fields are pointers so the
// handler can distinguish "absent" from "zero value". Only non-nil fields
// are forwarded into the Mongo `$set` payload.
//
// PER OLA-3 DECISION: all module PATCH bodies use `.strict()` semantics —
// unknown keys are rejected. The Node music body is the only one that
// silently drops them at the Mongoose layer; we tighten this to parity
// with greeter/logs (already `.strict()`).
type UpdateModuleMusicBody struct {
	SchemaVersion      *int                             `json:"schema_version,omitempty"`
	Enabled            *bool                            `json:"enabled,omitempty"`
	MaxSongDuration    *int                             `json:"max_song_duration,omitempty"`
	Loop               *dbguild.MusicLoop               `json:"loop,omitempty"`
	Volume             *int                             `json:"volume,omitempty"`
	RadioMode          *dbguild.RadioMode               `json:"radio_mode,omitempty"`
	MessageRetention   *bool                            `json:"message_retention,omitempty"`
	PinnedNowPlaying   *bool                            `json:"pinned_now_playing,omitempty"`
	VoiceStatusEnabled *bool                            `json:"voice_status_enabled,omitempty"`
	BotPoolEnabled     *bool                            `json:"bot_pool_enabled,omitempty"`
	EnhancedSearch     *bool                            `json:"enhanced_search,omitempty"`
	AutoDeleteCommands *[]string                        `json:"auto_delete_commands,omitempty"`
	AudioQuality       *dbguild.MusicAudioQuality       `json:"audio_quality,omitempty" validate:"omitempty,oneof=default hifi"`
	CommandsGlobal     *dbguild.MusicCommandAccess      `json:"commands_global,omitempty"`
	Commands           *map[string]dbguild.MusicCommand `json:"commands,omitempty"`
	TextChannels       *dbguild.ChannelsConfig          `json:"text_channels,omitempty"`
	VoiceChannels      *dbguild.ChannelsConfig          `json:"voice_channels,omitempty"`
	DJ                 *dbguild.DJ                      `json:"dj,omitempty"`
	RecommendedArtists *[]string                        `json:"recommended_artists,omitempty"`
}

// Set returns the BSON document for the `$set` payload. Returns nil when
// no fields were supplied so the repository can short-circuit and avoid
// issuing a no-op update.
func (b UpdateModuleMusicBody) Set() map[string]any {
	out := map[string]any{}
	if b.SchemaVersion != nil {
		out["schema_version"] = *b.SchemaVersion
	}
	if b.Enabled != nil {
		out["enabled"] = *b.Enabled
	}
	if b.MaxSongDuration != nil {
		out["max_song_duration"] = *b.MaxSongDuration
	}
	if b.Loop != nil {
		out["loop"] = string(*b.Loop)
	}
	if b.Volume != nil {
		out["volume"] = *b.Volume
	}
	if b.RadioMode != nil {
		out["radio_mode"] = *b.RadioMode
	}
	if b.MessageRetention != nil {
		out["message_retention"] = *b.MessageRetention
	}
	if b.PinnedNowPlaying != nil {
		out["pinned_now_playing"] = *b.PinnedNowPlaying
	}
	if b.VoiceStatusEnabled != nil {
		out["voice_status_enabled"] = *b.VoiceStatusEnabled
	}
	if b.BotPoolEnabled != nil {
		out["bot_pool_enabled"] = *b.BotPoolEnabled
	}
	if b.EnhancedSearch != nil {
		out["enhanced_search"] = *b.EnhancedSearch
	}
	if b.AutoDeleteCommands != nil {
		// Puntero + slice no vacío garantizado: el puntero distingue "no viene
		// en el PATCH" de "viene la lista vacía", que es un ajuste legítimo
		// ("no limpiar nada") y tiene que poder guardarse.
		list := *b.AutoDeleteCommands
		if list == nil {
			list = []string{}
		}
		out["auto_delete_commands"] = list
	}
	if b.AudioQuality != nil {
		out["audio_quality"] = string(*b.AudioQuality)
	}
	if b.CommandsGlobal != nil {
		out["commands_global"] = *b.CommandsGlobal
	}
	if b.Commands != nil {
		out["commands"] = *b.Commands
	}
	if b.TextChannels != nil {
		out["text_channels"] = *b.TextChannels
	}
	if b.VoiceChannels != nil {
		out["voice_channels"] = *b.VoiceChannels
	}
	if b.DJ != nil {
		out["dj"] = *b.DJ
	}
	if b.RecommendedArtists != nil {
		out["recommended_artists"] = *b.RecommendedArtists
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

// RadioModeEnabled is a helper for the controller's PATCH side-effect
// (`redisAdapter.cache.lavalink.setPlayerPersistent`). Returns nil when the
// PATCH body omits `radio_mode` entirely; otherwise a pointer to the new value.
//
// `radio_mode` is whole-object REPLACE, not merge: its fields are values, not
// pointers, so a body carrying `radio_mode` ALWAYS sets `enabled` - omitting
// the field inside it means `false`. That is not a quirk of this helper: `Set`
// above writes that same `false` to Mongo, so the two destinations stay in
// step. The shared TS type (`library-shared/src/db/schemas/DBGuildSchemas.ts`)
// declares both fields required, so no typed client can send the partial.
func (b UpdateModuleMusicBody) RadioModeEnabled() *bool {
	if b.RadioMode == nil {
		return nil
	}
	v := b.RadioMode.Enabled
	return &v
}

package validations

// UpdateModuleAutomationBody es el cuerpo del PATCH del módulo de
// automatizaciones. El handler lo decodifica con `DisallowUnknownFields` (el
// equivalente del `.strict()` de zod: una clave desconocida es un 400) y luego
// vuelve a decodificar el MISMO cuerpo crudo como `map[string]any`, que es lo
// que el repositorio mezcla con `mongo.MergeDeepJSON` por PRESENCIA de clave.
//
// Igual que en el resto de módulos, el PATCH NO expone `schema_version` ni
// `updated_at`: los estampa el repositorio en cada escritura. `enabled_since`
// tampoco, porque es WRITE-ONCE del servidor.
//
// AVISO sobre `automations`: el merge SUSTITUYE los arrays enteros, no los
// fusiona. Es justo lo que hace falta —así se puede BORRAR una automatización
// mandando la lista sin ella—, pero implica que quien escriba tiene que enviar
// la lista COMPLETA. Un PATCH con una sola automatización borra las demás.
//
// La forma de cada automatización NO se valida aquí. Quien la valida es el
// catálogo compartido (`@kena/shared/automation`) en las dos puntas: la
// dashboard antes de dejar publicar y el módulo antes de ejecutar. Repetir esas
// reglas en Go sería una tercera copia que se separaría de las otras dos, y la
// que peor se detecta: el documento se guardaría igual.
type UpdateModuleAutomationBody struct {
	Enabled          *bool             `json:"enabled,omitempty"`
	Automations      *[]map[string]any `json:"automations,omitempty"`
	LogChannelID     *string           `json:"log_channel_id,omitempty"`
	MaxActionsPerRun *int              `json:"max_actions_per_run,omitempty"`
}

package validations

import (
	"kena.bot/api-db-go/internal/domain/dbguild"
)

// UpdateModuleModerationBody mirrors the Node `updateModuleModerationSchema`
// (a `.strict()` object of `.optional()` fields). The handler decodes this
// with `DisallowUnknownFields` (matching the zod `.strict()` — unknown
// keys top-level OR nested are a 400) and then re-decodes the SAME raw
// body as `map[string]any`, which the repository merges into the existing
// subdoc via `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent in the
// body is left alone; an explicit `false`/`0`/`""`/`null` is applied and
// overrides the stored value; nested objects (`commands_global`, `mute`,
// `automod`) recurse; the `commands` map merges per-key; slices replace
// wholesale.
//
// UNLIKE the READ schema, the PATCH schema exposes NO `schema_version`
// / `updated_at` — those are stamped by the repo on every write. Every
// other READ field IS patchable here (the READ and PATCH catalogs
// otherwise match).
//
// `log_channel_id` is the only TOP-LEVEL nullable string (`string |
// null`). Because merge is presence-based, sending `null` clears it to
// null and omitting the key preserves the stored value — exactly like
// Node's `mergeDeep`, with no special-case handling in this struct. The
// nested nullables (`mute.role_id`, each command's `dm_embed.color`)
// ride inside their parent structs and are merged recursively.
//
// REMAINING CAVEATS (inherited from the old MergeDeep mold, NOT from
// presence-based behaviour):
//   - Go's json decoder does NOT enforce zod's REQUIRED-ness inside a
//     present nested object (Node's `commandAccessUpdateSchema` /
//     `automod*` rule schemas are `.strict()` with every field
//     required), so a partial nested object that Node would 400 is
//     accepted here and the missing leaves stay zero — the same
//     non-strict-required behaviour every Go module body has.
//   - The zod value constraints (`dm_embed.content` max 4000) are NOT
//     enforced here. Same as every other Go module body.
//
// Cada clave de nivel superior del schema DEBE tener su puntero aquí: si falta
// una, el PATCH de la dashboard se come un 400 "unknown field" (el handler
// decodifica con `DisallowUnknownFields`). Por eso los siete bloques del v3
// (`protection`, `escalation`, `effects`, `raid`, `gate`, `antinuke`,
// `lockdown`) están listados igual que `automod` — y `flows` (v4) igual.
//
// `Flows` reutiliza `dbguild.ModerationFlow` TAL CUAL (mismo precedente que
// `Creators *[]dbguild.TempvoiceCreator` / `TicketTypes *[]dbguild.TicketsType`
// / `TicketTypes *[]dbguild.ModmailTicketType`), no un tipo "Body" duplicado:
// el struct de dominio YA tiene exactamente la forma que la dashboard envía
// (§5.3 del contrato de flujos: el PATCH sustituye el array ENTERO, así que
// cada flujo llega completo, con `id`/`created_at`/`updated_at` incluidos).
// Los `params` de trigger/condiciones/pasos siguen siendo `map[string]any`
// libre — su forma la valida el catálogo compartido, no Go — así que
// `DisallowUnknownFields` no los toca; sí rechaza cualquier clave desconocida
// a nivel de `ModerationFlow`/`ModerationFlowScope`/etc., que es justo lo que
// se quiere.
type UpdateModuleModerationBody struct {
	Enabled            *bool                                 `json:"enabled,omitempty"`
	CommandMode        *dbguild.ModerationCommandMode        `json:"command_mode,omitempty"`
	CommandsGlobal     *dbguild.ModerationCommandAccess      `json:"commands_global,omitempty"`
	Commands           *map[string]dbguild.ModerationCommand `json:"commands,omitempty"`
	Mute               *dbguild.ModerationMute               `json:"mute,omitempty"`
	LogChannelID       *string                               `json:"log_channel_id,omitempty"`
	TrackNativeActions *bool                                 `json:"track_native_actions,omitempty"`
	Automod            *dbguild.ModerationAutomod            `json:"automod,omitempty"`
	Protection         *dbguild.ModerationProtection         `json:"protection,omitempty"`
	Escalation         *dbguild.ModerationEscalation         `json:"escalation,omitempty"`
	Effects            *dbguild.ModerationEffects            `json:"effects,omitempty"`
	Raid               *dbguild.ModerationRaid               `json:"raid,omitempty"`
	Gate               *dbguild.ModerationGate               `json:"gate,omitempty"`
	Antinuke           *dbguild.ModerationAntinuke           `json:"antinuke,omitempty"`
	Lockdown           *dbguild.ModerationLockdown           `json:"lockdown,omitempty"`
	Flows              *[]dbguild.ModerationFlow             `json:"flows,omitempty"`
}

package dbguild

import (
	"go.mongodb.org/mongo-driver/v2/bson"
)

// This file mirrors the `DBModuleModeration` family in
// `libraries/library-shared/src/db/schemas/DBGuildSchemas.ts`. The field
// ORDER of every struct matches the corresponding zod object schema in
// `apis/api-db/src/domain/zod-schemas/mongo/guild-schema.ts` (which happens to
// match the TS interface order): the Node GET response is produced by
// `moduleModerationSchema.parse(...)`, which normalises key order to the
// schema-definition order — so matching that order keeps the JSON body
// byte-for-byte identical.
//
// The moderation module is per-guild moderation CONFIG only (command mode +
// per-command access/DM, the hybrid-mute strategy, the mod-log channel, the
// AutoMod ruleset and — from v3 — the protection / escalation / effects / raid
// / gate / antinuke / lockdown blocks). The concrete sanctions (infractions)
// live in Postgres (`moderation.infractions`), NOT here.
//
// Nullable fields (`string | null` in TS) use pointer types so JSON encoding
// emits `null` (not `""`) for the unset variant: `log_channel_id`,
// `mute.role_id`, each command's `dm_embed.color`, and the v3
// `raid.alert_*`/`gate.alert_channel_id`/`antinuke.alert_*`. Collection fields
// (`[]string`, `Record<...>`) are never `omitempty`: a present-but-empty value
// must serialise as `[]` / `{}`, never `null`. `NormalizeModeration` backfills
// nil collections so the invariant holds for docs decoded from Mongo/Redis.
//
// Los defaults viven en ESTE paquete (y no en `mocks`) por dos razones: el
// paquete `mocks` ya importa `dbguild`, así que la migración no podría llamarlo
// sin ciclo; y así el seed del documento nuevo y el backfill del documento
// viejo comparten UNA sola fuente de verdad. Mismo patrón que
// `DefaultMusicCommands`.

// ModerationCommandMode mirrors `ModerationCommandMode` (`"slash" | "prefix" |
// "both"`) — how the moderation commands may be invoked (same pattern as
// tempvoice).
type ModerationCommandMode string

const (
	ModerationCommandModeSlash  ModerationCommandMode = "slash"
	ModerationCommandModePrefix ModerationCommandMode = "prefix"
	ModerationCommandModeBoth   ModerationCommandMode = "both"
)

// ModerationMuteMode mirrors `ModerationMuteMode` (`"auto" | "timeout" |
// "role"`) — the hybrid-mute application strategy (native timeout ≤28d / silence
// role).
type ModerationMuteMode string

const (
	ModerationMuteModeAuto    ModerationMuteMode = "auto"
	ModerationMuteModeTimeout ModerationMuteMode = "timeout"
	ModerationMuteModeRole    ModerationMuteMode = "role"
)

// ModerationAccessMode mirrors `DBAccessMode` (`"only" | "all_except"`) — the
// mode of a command access list. `only` = allowlist, `all_except` = denylist.
// Defined locally (not shared with tempvoice) to keep the verticals decoupled,
// matching how tempvoice/modmail each define their own.
type ModerationAccessMode string

const (
	ModerationAccessOnly      ModerationAccessMode = "only"
	ModerationAccessAllExcept ModerationAccessMode = "all_except"
)

// AutomodAction mirrors `AutomodAction` (`"delete" | "delete_warn" |
// "delete_timeout" | "delete_kick" | "delete_ban"`) — what the AutoMod does when
// a rule fires: delete only, delete + DM warning, delete + tempmute
// (`timeout_ms`), delete + kick, or delete + ban. Los tres primeros son los del
// v2 y siguen siendo válidos: la ampliación del v3 es ADITIVA y ningún
// documento existente necesita migrarse por ella.
type AutomodAction string

const (
	AutomodActionDelete        AutomodAction = "delete"
	AutomodActionDeleteWarn    AutomodAction = "delete_warn"
	AutomodActionDeleteTimeout AutomodAction = "delete_timeout"
	AutomodActionDeleteKick    AutomodAction = "delete_kick"
	AutomodActionDeleteBan     AutomodAction = "delete_ban"
)

// ModerationEscalationAction mirrors `ModerationEscalationAction` — la sanción
// que aplica un peldaño del escalado automático.
type ModerationEscalationAction string

const (
	ModerationEscalationMute     ModerationEscalationAction = "mute"
	ModerationEscalationTempmute ModerationEscalationAction = "tempmute"
	ModerationEscalationKick     ModerationEscalationAction = "kick"
	ModerationEscalationTempban  ModerationEscalationAction = "tempban"
	ModerationEscalationBan      ModerationEscalationAction = "ban"
)

// InfractionCountableType mirrors `InfractionCountableType` — los tipos de
// infracción que pueden sumar al contador del escalado automático.
type InfractionCountableType string

const (
	InfractionCountableWarn     InfractionCountableType = "warn"
	InfractionCountableNote     InfractionCountableType = "note"
	InfractionCountableMute     InfractionCountableType = "mute"
	InfractionCountableTempmute InfractionCountableType = "tempmute"
	InfractionCountableKick     InfractionCountableType = "kick"
	InfractionCountableBan      InfractionCountableType = "ban"
	InfractionCountableTempban  InfractionCountableType = "tempban"
)

// ModerationEffectPolicy mirrors `ModerationEffectPolicy` — cuándo se aplica un
// efecto secundario de sanción: siempre, nunca, o lo decide el moderador en el
// momento (`ask`, que cae en `default` si no pasa la opción).
type ModerationEffectPolicy string

const (
	ModerationEffectAlways ModerationEffectPolicy = "always"
	ModerationEffectNever  ModerationEffectPolicy = "never"
	ModerationEffectAsk    ModerationEffectPolicy = "ask"
)

// ModerationRaidAction mirrors `ModerationRaidAction` — qué hace el módulo
