package validations

import (
	"strconv"

	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// UpdateModuleGreeterBody mirrors the Node `updateModuleGreeterSchema`
// (which is `greeterSchema.partial()`). All fields are pointers so the
// strict decoder can validate the shape (enums / nested structs) before
// the handler re-decodes the raw body as `map[string]any` and forwards
// it to the repository, which `mongo.MergeDeepJSON`-merges it into the
// existing subdoc by KEY PRESENCE (a key absent in the body is left
// alone; an explicit `false`/`0`/`""`/`null` is applied and overrides
// the stored value; nested objects recurse; slices replace wholesale;
// maps merge per-key).
//
// PER OLA-3 NOTE: this body is NOT strict. The handler binds with Fiber's
// default decoder (`c.Bind().Body`), which silently drops unknown keys —
// parity with Mongoose, same as logs/music. Only modmail/tempvoice/giveaway/
// moderation call `DisallowUnknownFields`; see the matching note in
// `module_tempvoice_validations.go`.
//
// Consequence to keep in mind: a client typo returns 200 as if it had been
// applied. It does not corrupt data — `MergeDeepJSON` drops any key that
// matches no json tag — and the server-owned fields (`schema_version`,
// `updated_at`, `enabled_since`) are re-stamped by the repository even if a
// client sends them, which is what keeps the write-once `enabled_since`
// invariant safe. See `module_greeter_repository.go`.
type UpdateModuleGreeterBody struct {
	Enabled *bool                         `json:"enabled,omitempty"`
	Welcome *dbguild.GreeterMessageConfig `json:"welcome,omitempty"`
	Goodbye *dbguild.GreeterMessageConfig `json:"goodbye,omitempty"`
	Boost   *dbguild.GreeterMessageConfig `json:"boost,omitempty"`
	// Hermano de `boost` en la forma, pero depende de él en comportamiento:
	// la reacción marca el mensaje que `boost` publica (ver
	// `DBGreeterBoostReaction` en library-shared). Va fuera porque `boost`
	// comparte forma con welcome/goodbye, donde no significaría nada.
	BoostReaction *dbguild.GreeterBoostReaction `json:"boost_reaction,omitempty"`
	JoinRoles     *dbguild.JoinRoles            `json:"join_roles,omitempty"`
	Captcha       *dbguild.GreeterCaptcha       `json:"captcha,omitempty"`
	Variables     *dbguild.GreeterVariables     `json:"variables,omitempty"`
}

// Límites duros de la API de Discord. No son gusto nuestro: pasarse de aquí
// hace que Discord rechace el mensaje con 400 y la bienvenida NUNCA salga -en
// silencio, porque el error sólo aparece en los logs del bot-. Antes no había
// tope en ninguna capa: ni aquí, ni en el zod del dashboard. 32 KB de
// `message.content` se persistían tan contentos y el guild se quedaba sin
// bienvenidas para siempre.
const (
	maxGreeterContent     = 2000
	maxGreeterEmbedTitle  = 256
	maxGreeterEmbedDesc   = 4096
	maxGreeterEmbedFooter = 2048
	maxGreeterURL         = 2048
	maxGreeterButtonLabel = 80

	// Discord no deja más de 250 roles por servidor, así que una lista más
	// larga sólo puede ser basura o un intento de ahogar al bot: asigna con un
	// `for` secuencial y DOS llamadas a la API por rol.
	maxJoinRoles = 250

	// Cada capa de tipo `image`/`avatar` es una descarga remota más, en serie,
	// por cada miembro que entra.
	maxCanvasElements = 100

	// 4096x4096 en RGBA son 64 MB de heap NATIVO, que `--max-old-space-size`
	// no acota. Sin techo, `width: 50000` pedía ~10 GB y se llevaba por delante
	// el proceso que sirve a TODOS los guilds.
	maxCanvasSide = 4096

	// 14 días. Por encima de 2^31-1 milisegundos (~24,8 días) `setTimeout` de
	// Node desborda, avisa con `TimeoutOverflowWarning` y coacciona el retardo
	// a 1 ms: el mensaje que debía borrarse dentro de un mes se borraba al
	// instante. Invertía la intención del usuario sin decir nada.
	maxDelaySeconds = 14 * 24 * 60 * 60
)

func maxLen(value *string, limit int, property string) *apierrors.CustomError {
	if value == nil || len([]rune(*value)) <= limit {
		return nil
	}
	return zodItemError(
		"Too big: expected string to have <="+strconv.Itoa(limit)+" characters",
		property,
	)
}

func inRange(value *int, limit int, property string) *apierrors.CustomError {
	if value == nil {
		return nil
	}
	if *value < 0 {
		return zodItemError("Too small: expected number to be >=0", property)
	}
	if *value > limit {
		return zodItemError(
			"Too big: expected number to be <="+strconv.Itoa(limit),
			property,
		)
	}
	return nil
}

func validateGreeterEmbed(e *dbguild.GreeterEmbed, prefix string) *apierrors.CustomError {
	if e == nil {
		return nil
	}
	for _, c := range []struct {
		value    *string
		limit    int
		property string
	}{
		{e.Title, maxGreeterEmbedTitle, prefix + "title"},
		{e.Description, maxGreeterEmbedDesc, prefix + "description"},
		{e.Footer, maxGreeterEmbedFooter, prefix + "footer"},
		{e.ImageURL, maxGreeterURL, prefix + "image_url"},
		{e.ThumbnailURL, maxGreeterURL, prefix + "thumbnail_url"},
	} {
		if err := maxLen(c.value, c.limit, c.property); err != nil {
			return err
		}
	}
	return nil
}

// validateGreeterImage aplica los topes del bloque `image` (tamaño de
// canvas, nº de elementos, longitud de URLs). Canal y privado comparten esta
// función -mismo tipo `dbguild.GreeterImage`, mismos límites- porque un
// canvas de privado puede llegar por PATCH directo igual que el de canal:
// nada en el transporte HTTP distingue a uno del otro, así que ambos
// necesitan el mismo candado. `prefix` ya incluye el segmento propio con el
// punto final (p.ej. "welcome.image." o "welcome.dm.image."), igual que hace
// validateGreeterEmbed con el suyo.
func validateGreeterImage(img *dbguild.GreeterImage, prefix string) *apierrors.CustomError {
	if err := maxLen(img.BackgroundURL, maxGreeterURL, prefix+"background_url"); err != nil {
		return err
	}

	canvas := &img.Canvas
	if canvas.Width > maxCanvasSide || canvas.Height > maxCanvasSide {
		return zodItemError(
			"Too big: expected number to be <="+strconv.Itoa(maxCanvasSide),
			prefix+"canvas",
		)
	}
	if canvas.Width < 0 || canvas.Height < 0 {
		return zodItemError("Too small: expected number to be >=0", prefix+"canvas")
	}
	if len(canvas.Elements) > maxCanvasElements {
		return zodItemError(
			"Too big: expected array to have <="+strconv.Itoa(maxCanvasElements)+" items",
			prefix+"canvas.elements",
		)
	}
	if err := maxLen(
		canvas.BackgroundURL,
		maxGreeterURL,
		prefix+"canvas.background_url",
	); err != nil {
		return err
	}
	for i := range canvas.Elements {
		if err := maxLen(
			canvas.Elements[i].URL,
			maxGreeterURL,
			prefix+"canvas.elements."+strconv.Itoa(i)+".url",
		); err != nil {
			return err
		}
	}
	return nil
}

func validateGreeterMessageConfig(
	c *dbguild.GreeterMessageConfig,
	prefix string,
) *apierrors.CustomError {
	if c == nil {
		return nil
	}

	if err := maxLen(&c.Message.Content, maxGreeterContent, prefix+"message.content"); err != nil {
		return err
	}
	if err := validateGreeterEmbed(&c.Embed, prefix+"embed."); err != nil {
		return err
	}
	if err := maxLen(&c.DM.Message.Content, maxGreeterContent, prefix+"dm.message.content"); err != nil {
		return err
	}
	if err := validateGreeterEmbed(&c.DM.Embed, prefix+"dm.embed."); err != nil {
		return err
	}
	if err := inRange(
		c.Behavior.DeleteAfterSeconds,
		maxDelaySeconds,
		prefix+"behavior.delete_after_seconds",
	); err != nil {
		return err
	}
	if err := inRange(
		c.DM.DeleteAfterSeconds,
		maxDelaySeconds,
		prefix+"dm.delete_after_seconds",
	); err != nil {
		return err
	}
	// El canvas de privado puede llegar por PATCH directo igual que el de
	// canal -nada en el transporte los distingue-, así que se valida con los
	// mismos topes. Ver validateGreeterImage.
	if err := validateGreeterImage(&c.Image, prefix+"image."); err != nil {
		return err
	}
	if err := validateGreeterImage(&c.DM.Image, prefix+"dm.image."); err != nil {
		return err
	}
	return nil
}

// ValidateUpdateModuleGreeter aplica los topes que faltaban por completo en el
// servidor. El zod del dashboard sí revalida en su propio servidor, pero eso
// sólo cubre a quien entra POR el dashboard: este endpoint acepta un PATCH
// directo con la credencial de api-db y no tenía nada que lo parase.
//
// Sólo mira lo que el cuerpo trae: `UpdateModuleGreeterBody` es un parcial y
// un puntero nil significa «no tocar este bloque», no «vacío».
func ValidateUpdateModuleGreeter(body *UpdateModuleGreeterBody) *apierrors.CustomError {
	for _, b := range []struct {
		config *dbguild.GreeterMessageConfig
		prefix string
	}{
		{body.Welcome, "welcome."},
		{body.Goodbye, "goodbye."},
		{body.Boost, "boost."},
	} {
		if err := validateGreeterMessageConfig(b.config, b.prefix); err != nil {
			return err
		}
	}

	if body.JoinRoles != nil {
		if len(body.JoinRoles.RolesID) > maxJoinRoles {
			return zodItemError(
				"Too big: expected array to have <="+strconv.Itoa(maxJoinRoles)+" items",
				"join_roles.roles_id",
			)
		}
		if err := inRange(
			body.JoinRoles.DelaySeconds,
			maxDelaySeconds,
			"join_roles.delay_seconds",
		); err != nil {
			return err
		}
	}

	if body.Captcha != nil {
		if err := maxLen(
			&body.Captcha.ButtonLabel,
			maxGreeterButtonLabel,
			"captcha.button_label",
		); err != nil {
			return err
		}
		if e := body.Captcha.WelcomeEmbed; e != nil {
			if err := maxLen(&e.Title, maxGreeterEmbedTitle, "captcha.welcome_embed.title"); err != nil {
				return err
			}
			if err := maxLen(
				&e.Description,
				maxGreeterEmbedDesc,
				"captcha.welcome_embed.description",
			); err != nil {
				return err
			}
			if err := maxLen(e.Footer, maxGreeterEmbedFooter, "captcha.welcome_embed.footer"); err != nil {
				return err
			}
		}
	}

	return nil
}

package dbguild

import (
	"bytes"
	"encoding/json"

	"go.mongodb.org/mongo-driver/v2/bson"
)

// This file mirrors the `DBModuleMusic` family in
// `libraries/library-shared/src/db/schemas/DBGuildSchemas.ts`. The field
// ORDER of `ModuleMusic` matches the zod object schema in
// `apis/api-db/src/domain/zod-schemas/mongo/guild-schema.ts`
// (`moduleMusicSchema`) — the Node GET response is produced by
// `moduleMusicMigrationSchema.parse(...)`, which normalises key order to the
// schema-definition order, so matching that order keeps the JSON body
// byte-for-byte identical. Notably `commands_global` + `commands` sit BETWEEN
// `enhanced_search` and `text_channels` (where the removed `blocked_commands`
// used to live).
//
// SCHEMA v5 ("command access"): Node replaced the flat `blocked_commands:
// string[]` with the rich per-command access model shared with tempvoice —
// `commands_global` (DBCommandAccess) + `commands` (map keyed by slash name).
// The `dj` block is UNCHANGED and stays. The v5 zod preprocess migrates an old
// doc on read: `blocked_commands → commands[cmd].enabled=false`. See
// `MigrateMusicRaw`.
//
// Music's per-command `use_global` is the PER-AXIS object `{roles, channels,
// categories}` (Node commit b4f57ff switched it from a bare boolean; the
// version constant stayed 5), IDENTICAL in shape to tempvoice's
// `DBTempVoiceCommand`. The types are defined locally (not shared with
// tempvoice) to keep the verticals decoupled, matching moderation/modmail.

// MusicLoop mirrors the TS `DBMusicLoop` enum. JSON values are the lowercase
// strings — keep them in sync with `libraries/library-shared/src/db/schemas/DBGuildSchemas.ts`.
type MusicLoop string

const (
	MusicLoopNone  MusicLoop = "none"
	MusicLoopSong  MusicLoop = "song"
	MusicLoopQueue MusicLoop = "queue"
)

// MusicAudioQuality mirrors the TS `DBMusicAudioQuality` enum (schema v7).
// "hifi" asks api-music for FLAC (`/file/:id?format=flac`); it only takes
// effect for premium guilds and behind music-module's MUSIC_HIFI_ENABLED
// deploy flag. JSON values are the lowercase strings — keep in sync with
// `libraries/library-shared/src/db/schemas/DBGuildSchemas.ts`.
type MusicAudioQuality string

const (
	MusicAudioQualityDefault MusicAudioQuality = "default"
	MusicAudioQualityHifi    MusicAudioQuality = "hifi"
)

// VolumeDefaults mirrors the TS `DBVolumeDefaults` constant. Kept here for
// callers that want the same baselines without round-tripping through Mongo.
const (
	VolumeDefault = 40
	VolumeMin     = 0
	VolumeMax     = 100
)

// RadioMode tracks the "24/7 stay-in-channel" toggle (legacy-named "radio").
// `channel_id` is empty when disabled; never null in the Node service.
type RadioMode struct {
	Enabled   bool   `bson:"enabled"    json:"enabled"`
	ChannelID string `bson:"channel_id" json:"channel_id"`
}

// RadioModeGuild is one row of "which guilds of this bot have 24/7 on, and in
// which channel".
//
// It exists because there was no way to ask that question. The music module
// rebuilds players at boot from a Redis set of guilds that HAD a live player,
// so a 24/7 guild whose player was lost (node restart, session teardown, or the
// long-lived bug that let the idle timer collect persistent players) never came
// back on its own — Mongo still said "stay in channel X" and nobody ever read
// it. Asking guild-by-guild would be thousands of requests per boot.
//
// Declared here, in the shared domain package, so the `mongorepo` interface and
// the `mongo` implementation name the SAME type: those two packages duplicate
// their envelope types deliberately and only line up structurally.
type RadioModeGuild struct {
	GuildID   string `bson:"guild_id"   json:"guild_id"`
	ChannelID string `bson:"channel_id" json:"channel_id"`
}

// ChannelsConfig captures the include/exclude list used by both text and
// voice channel filters. `Exclude=true` flips the list semantics from
// "only these channels" to "every channel except these".
//
// `ShowAllowedChannels` hace que el módulo, al rechazar un comando por esta
// regla, añada al aviso la lista de canales donde SÍ se puede usar el bot.
// No necesita migración: el default es `false` y coincide con el valor cero de
// Go, así que un documento antiguo sin la clave se decodifica ya apagado.
type ChannelsConfig struct {
	Exclude             bool     `bson:"exclude"               json:"exclude"`
	ChannelsID          []string `bson:"channels_id"           json:"channels_id"`
	ShowAllowedChannels bool     `bson:"show_allowed_channels" json:"show_allowed_channels"`
}

// DJ holds the DJ subsystem flags. `Vote=true` enables consensus voting on
// queue-affecting commands; `Vote=false` falls back to "must have a DJ role".
// `Enabled=false` short-circuits the entire subsystem — bypasses included.
type DJ struct {
	Enabled     bool     `bson:"enabled"      json:"enabled"`
	Roles       []string `bson:"roles"        json:"roles"`
	Commands    []string `bson:"commands"     json:"commands"`
	Vote        bool     `bson:"vote"         json:"vote"`
	VoteTimeout int      `bson:"vote_timeout" json:"vote_timeout"`
}

// MusicAccessMode mirrors `DBAccessMode` (`"only" | "all_except"`) — the mode
// of a command access list. `only` = allowlist, `all_except` = denylist.
type MusicAccessMode string

const (
	MusicAccessOnly      MusicAccessMode = "only"
	MusicAccessAllExcept MusicAccessMode = "all_except"
)

// MusicAccessList mirrors `DBAccessList` — the roles/channels/categories access
// list of a music command. Field order follows `accessListSchema`.
type MusicAccessList struct {
	Mode MusicAccessMode `bson:"mode" json:"mode"`
	IDs  []string        `bson:"ids"  json:"ids"`
}

// MusicCommandAccess mirrors `DBCommandAccess` — the per-axis access of a
// command (who: roles, where: channels/categories). Field order follows the
// zod `commandAccessSchema`.
type MusicCommandAccess struct {
	Roles      MusicAccessList `bson:"roles"      json:"roles"`
	Channels   MusicAccessList `bson:"channels"   json:"channels"`
	Categories MusicAccessList `bson:"categories" json:"categories"`
}

// MusicCommandSync mirrors `DBTempVoiceCommandSync` — the per-axis inheritance
// of the module's global access. A `true` axis reads from `commands_global`; a
// `false` axis reads from the command's own `access`. (Music's `use_global`
// became this object in Node commit b4f57ff; the schema constant stayed 5.)
type MusicCommandSync struct {
	Roles      bool `bson:"roles"      json:"roles"`
	Channels   bool `bson:"channels"   json:"channels"`
	Categories bool `bson:"categories" json:"categories"`
}

// legacySyncBool reports whether a raw JSON value is the legacy bare boolean
// shape of `use_global` (pre per-axis expansion). Shared by the music and
// tempvoice sync unmarshalers.
func legacySyncBool(b []byte) (value, ok bool) {
	switch string(bytes.TrimSpace(b)) {
	case "true":
		return true, true
	case "false":
		return false, true
	}
	return false, false
}

// UnmarshalJSON accepts the current per-axis object AND the legacy bare
// boolean (`"use_global": true`) still present in prod guild docs / cache
// hashes written before Node commit b4f57ff. The bool expands to all three
// axes, mirroring `musicCommandFromRaw` / Node's zod preprocess. Without
// this, a direct struct decode of a legacy doc fails (prod 500, 2026-07-18:
// `module_music.commands.247.use_global`).
func (s *MusicCommandSync) UnmarshalJSON(b []byte) error {
	if v, ok := legacySyncBool(b); ok {
		*s = MusicCommandSync{Roles: v, Channels: v, Categories: v}
		return nil
	}
	type plain MusicCommandSync
	var p plain
	if err := json.Unmarshal(b, &p); err != nil {
		return err
	}
	*s = MusicCommandSync(p)
	return nil
}

// UnmarshalBSONValue is the BSON twin of UnmarshalJSON — the Mongo cold path
// (`FindOne(...).Decode(&guild)`) hits the same legacy boolean.
func (s *MusicCommandSync) UnmarshalBSONValue(t byte, data []byte) error {
	switch bson.Type(t) {
	case bson.TypeBoolean:
		var v bool
		if err := bson.UnmarshalValue(bson.TypeBoolean, data, &v); err != nil {
			return err
		}
		*s = MusicCommandSync{Roles: v, Channels: v, Categories: v}
		return nil
	case bson.TypeNull:
		*s = MusicCommandSync{}
		return nil
	default:
		type plain MusicCommandSync
		var p plain
		if err := bson.UnmarshalValue(bson.Type(t), data, &p); err != nil {
			return err
		}
		*s = MusicCommandSync(p)
		return nil
	}
}

// MusicCommand mirrors a music `commands` entry (same shape as
// `DBTempVoiceCommand`): enabled + GRANULAR per-axis global inheritance
// (`use_global.{roles,channels,categories}`) + the command's own `access`.
// Field order follows the zod `tempvoiceConfigurableCommandSchema` used for
// music's `commands`.
type MusicCommand struct {
	Enabled   bool               `bson:"enabled"    json:"enabled"`
	UseGlobal MusicCommandSync   `bson:"use_global" json:"use_global"`
	Access    MusicCommandAccess `bson:"access"     json:"access"`
}

// ModuleMusic matches `DBModuleMusic` in TS (schema v5). Field order follows
// `moduleMusicSchema`: `commands_global` + `commands` sit between
// `enhanced_search` and `text_channels`. Collection fields (`Commands` map,
// the access-list ID slices, `[]string`) are never `omitempty`: a
// present-but-empty value must serialise as `{}` / `[]`, never `null`.
// `NormalizeMusic` backfills nil collections so the invariant holds for docs
// decoded from Mongo/Redis.
type ModuleMusic struct {
	SchemaVersion      int                     `bson:"schema_version"       json:"schema_version"`
	Enabled            bool                    `bson:"enabled"              json:"enabled"`
	// EnabledSince es la fecha de la PRIMERA activación del módulo en este
	// guild — WRITE-ONCE: se estampa al activar por primera vez y no se
	// reescribe nunca (ni al desactivar ni al reactivar). Sostiene el
	// derecho legacy: un guild que activó music antes del corte de
	// `globals.module_premium_cutoffs` conserva el módulo entero gratis.
	// `nil` (campo ausente en Mongo) = nunca activado.
	EnabledSince       *JSONDate               `bson:"enabled_since,omitempty" json:"enabled_since"`
	MaxSongDuration    int                     `bson:"max_song_duration"    json:"max_song_duration"`
	Loop               MusicLoop               `bson:"loop"                 json:"loop"`
	Volume             int                     `bson:"volume"               json:"volume"`
	RadioMode          RadioMode               `bson:"radio_mode"           json:"radio_mode"`
	MessageRetention   bool                    `bson:"message_retention"    json:"message_retention"`
	PinnedNowPlaying   bool                    `bson:"pinned_now_playing"   json:"pinned_now_playing"`
	VoiceStatusEnabled bool                    `bson:"voice_status_enabled" json:"voice_status_enabled"`
	// BotPoolEnabled activa el reparto automático de la reproducción entre los
	// bots Kena presentes en el servidor cuando el bot que recibe el comando ya
	// está sonando en otro canal de voz.
	BotPoolEnabled     bool                    `bson:"bot_pool_enabled"     json:"bot_pool_enabled"`
	EnhancedSearch     bool                    `bson:"enhanced_search"      json:"enhanced_search"`
	AutoDeleteCommands []string                `bson:"auto_delete_commands" json:"auto_delete_commands"`
	AudioQuality       MusicAudioQuality       `bson:"audio_quality"        json:"audio_quality"`
	CommandsGlobal     MusicCommandAccess      `bson:"commands_global"      json:"commands_global"`
	Commands           map[string]MusicCommand `bson:"commands"             json:"commands"`
	TextChannels       ChannelsConfig          `bson:"text_channels"        json:"text_channels"`
	VoiceChannels      ChannelsConfig          `bson:"voice_channels"       json:"voice_channels"`
	DJ                 DJ                      `bson:"dj"                   json:"dj"`
	RecommendedArtists []string                `bson:"recommended_artists"  json:"recommended_artists"`
}

// MusicCommandNames mirrors `MUSIC_COMMANDS` in `guild-mock.ts` — the 25
// configurable music slash names, in the SAME order. Keep in sync with the
// module guard and the dashboard schema.
var MusicCommandNames = []string{
	"247",
	"autoplay",
	"clearafter",
	"clearqueue",
	"dedupe",
