// MusicAutoDeleteCommandsDefault mirrors `DBMusicAutoDeleteCommandsDefault` in
// `library-shared`'s `DBGuildSchemas.ts` — the commands whose usage was ALREADY
// being cleaned from chat before the list existed, under the default config.
// Seeding exactly these is what makes the v8 field invisible to existing guilds.
//
// The first 16 carried a hardcoded `delete_after: true`; the last four derived
// it from `message_retention`, whose default is `false`, so in practice they
// were cleaned too. `queue`, `nowplaying`, `filters` and `play` stay out on
// purpose: their replies are panels/listings that would be useless if they
// vanished after 5s. Keep in sync with the dashboard default and the module.
var MusicAutoDeleteCommandsDefault = []string{
	"skip",
	"pause",
	"resume",
	"stop",
	"loop",
	"volume",
	"shuffle",
	"seek",
	"previous",
	"remove",
	"insert",
	"skipto",
	"clearqueue",
	"clearafter",
	"dedupe",
	"repair",
	"autoplay",
	"radio",
	"lofi",
	"247",
	MusicPlayerButtonsKey,
}

// MusicPlayerButtonsKey is the RESERVED entry of `auto_delete_commands` covering
// the player buttons (⏯ ⏭ ⏮ 🔀 🔁) as a single block. Deliberately not a command
// name: buttons are a separate surface, so a guild can clean the typed `!skip`
// but keep the button's reply, or the other way round. Mirrors
// `DB_MUSIC_PLAYER_BUTTONS_KEY` in library-shared and the dashboard.
//
// Nothing validates the list against MusicCommandNames, which is what makes the
// sentinel possible — keep it that way.
const MusicPlayerButtonsKey = "player_buttons"

// MusicCommandAccessDefault mirrors `musicCommandAccessDefault()` in
// `guild-mock.ts`: UNRESTRICTED on all three axes (`all_except []`). Unlike
// tempvoice it does NOT seed the temp-channel sentinel — music has no temporary
// channel, so `channels` starts as `all_except []`. Fresh slices each call.
func MusicCommandAccessDefault() MusicCommandAccess {
	return MusicCommandAccess{
		Roles:      MusicAccessList{Mode: MusicAccessAllExcept, IDs: []string{}},
		Channels:   MusicAccessList{Mode: MusicAccessAllExcept, IDs: []string{}},
		Categories: MusicAccessList{Mode: MusicAccessAllExcept, IDs: []string{}},
	}
}

// MusicConfigurableCommandDefault mirrors `musicConfigurableCommandDefault()`:
// enabled, inheriting the global access on all three axes. Fresh slices each
// call.
func MusicConfigurableCommandDefault() MusicCommand {
	return MusicCommand{
		Enabled:   true,
		UseGlobal: MusicCommandSync{Roles: true, Channels: true, Categories: true},
		Access:    MusicCommandAccessDefault(),
	}
}

// DefaultMusicCommands mirrors `createDefaultMusicCommands()` — every
// `MUSIC_COMMANDS` entry enabled + inheriting the global access. Allocates a
// fresh map and fresh per-entry slices each call so callers can mutate the
// result without bleeding into other docs.
func DefaultMusicCommands() map[string]MusicCommand {
	out := make(map[string]MusicCommand, len(MusicCommandNames))
	for _, name := range MusicCommandNames {
		out[name] = MusicConfigurableCommandDefault()
	}
	return out
}

// NormalizeMusic backfills every collection field that decoded as `nil` (from a
// partial Mongo doc or a legacy cache entry) with a non-nil empty value,
// mirroring the zod `.default([])` / `.default({})`. This keeps the JSON body
// emitting `[]` / `{}` instead of `null` — the exact shape the Node service
// produces after re-parsing through `moduleMusicSchema`. Idempotent.
func NormalizeMusic(m *ModuleMusic) {
	if m == nil {
		return
	}
	m.RecommendedArtists = ensureMusicStrSlice(m.RecommendedArtists)
	m.TextChannels.ChannelsID = ensureMusicStrSlice(m.TextChannels.ChannelsID)
	m.VoiceChannels.ChannelsID = ensureMusicStrSlice(m.VoiceChannels.ChannelsID)
	m.DJ.Roles = ensureMusicStrSlice(m.DJ.Roles)
	m.DJ.Commands = ensureMusicStrSlice(m.DJ.Commands)

	// v7 additive field: docs/cache entries older than v7 decode with the Go
	// zero value ("") — backfill the zod default, mirroring
	// `audio_quality: z.enum(...).default("default")`.
	if m.AudioQuality == "" {
		m.AudioQuality = MusicAudioQualityDefault
	}

	// v8 additive field. A `nil` slice here means the key was absent from the
	// document, so the guild never configured the list and gets the seed; a
	// stored empty array decodes as a non-nil empty slice and is preserved,
	// because "clean nothing" is a valid choice.
	//
	// Esa distinción nil/vacío es la que sostiene el campo entero, y por eso
	// NO se pasa por `ensureMusicStrSlice` como el resto de colecciones: ahí
	// ausente y vacío significan lo mismo y aquí no.
	//
	// Hace falta además de la comprobación de presencia de `MigrateMusicRaw`
	// porque `ModuleMusicRepository.Update` decodifica el resultado del
	// FindOneAndUpdate directamente al struct, sin pasar por la migración: sin
	// esto, un PATCH de cualquier otro campo escribiría la lista vacía en el
	// hash de Redis y envenenaría los cache-hits siguientes.
	if m.AutoDeleteCommands == nil {
		m.AutoDeleteCommands = append([]string(nil), MusicAutoDeleteCommandsDefault...)
	}

	normalizeMusicAccess(&m.CommandsGlobal)

	if m.Commands == nil {
		m.Commands = map[string]MusicCommand{}
	} else {
		for k, v := range m.Commands {
			normalizeMusicAccess(&v.Access)
			m.Commands[k] = v
		}
	}
}

// normalizeMusicAccess backfills the three access-list ID slices of a
// command-access block so each serialises as `[]`, y repone el `mode` cuando
// llega vacío.
//
// `mode` es un enum (`only` | `all_except`) y la cadena vacía no es un valor:
// sale del decode directo de un bloque que NO existe en el documento. El
// dashboard lo pinta como un select en blanco y su zod lo rechaza al guardar,
// así que se repone el default (`all_except []` = sin restricción), igual que
// se hace con `audio_quality`.
func normalizeMusicAccess(a *MusicCommandAccess) {
	normalizeMusicAccessList(&a.Roles)
	normalizeMusicAccessList(&a.Channels)
	normalizeMusicAccessList(&a.Categories)
}

func normalizeMusicAccessList(l *MusicAccessList) {
	if l.Mode == "" {
		l.Mode = MusicAccessAllExcept
	}
	l.IDs = ensureMusicStrSlice(l.IDs)
}

// MusicAccessComplete indica si un bloque de acceso trae los tres ejes con su
// enum poblado. Se usa para decidir si una entrada de CACHÉ es aprovechable:
// un hash escrito antes del fix del PATCH (decode directo de un documento
// pre-v5) trae los tres `mode` en blanco, y la caché es el único camino que no
// pasa por la migración, así que sin esta comprobación se serviría tal cual
// hasta que expirase el TTL (24 h).
func MusicAccessComplete(a MusicCommandAccess) bool {
	return a.Roles.Mode != "" && a.Channels.Mode != "" && a.Categories.Mode != ""
}

func ensureMusicStrSlice(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

// MusicRawSchemaVersion reads the `schema_version` from a raw (lean) Mongo
// `module_music` subdoc, tolerating the int32/int64/int/float64 shapes the bson
// and JSON decoders can produce. Returns 0 when absent — the repo treats a
// zero/empty subdoc as "apply full defaults" (mirrors Node's
// `parseModule(rawModuleData ?? {})`).
func MusicRawSchemaVersion(raw bson.M) int {
	switch v := raw["schema_version"].(type) {
	case int:
		return v
	case int32:
		return int(v)
	case int64:
		return int(v)
	case float64:
		return int(v)
	}
	return 0
}

// MigrateMusicRaw upgrades a raw (lean POJO) `module_music` subdoc to the
// current v7 typed shape, replicating the Node `moduleMusicMigrationSchema`
// preprocess followed by the `moduleMusicSchema` zod defaults:
//
//   - v4 → v5: `blocked_commands: string[]` becomes, for each listed command,
//     `commands[cmd].enabled = false` (the rest of the entry defaults:
//     use_global all-true, access `all_except []` on every axis), merging into
//     any pre-existing `commands` map. `blocked_commands` is dropped. When there
//     is NO `commands` key and NO blocked list, `commands` defaults to the full
//     `MUSIC_COMMANDS` set (every command enabled).
//   - legacy `use_global: boolean` (music's original v5, pre-b4f57ff) expands to
//     the per-axis `{roles, channels, categories}` object per command.
//   - `commands_global` defaults to unrestricted (`all_except []`) when absent.
//   - v7: `audio_quality` absent (every pre-v7 doc) → "default".
//   - stamps `schema_version = 7` (SchemaVersionMusic).
//
// It overlays present raw leaves onto the defaults (never trusting Go's
// zero-value for an absent leaf — a legacy `{enabled:false}` entry still gets
// `use_global` all-true), so the result matches Node's zod-with-defaults
// field-for-field. Idempotent: a doc already in v7 shape round-trips unchanged.
func MigrateMusicRaw(raw bson.M) ModuleMusic {
	var m ModuleMusic
	// Base decode of the STABLE fields (everything except the command-access
	// maps, which need overlay-onto-default semantics and can carry a legacy
	// boolean `use_global` that would not decode into the struct).
	if b, err := bson.Marshal(stripMusicCommandKeys(raw)); err == nil {
		_ = bson.Unmarshal(b, &m)
	}

	m.CommandsGlobal = musicAccessFromRaw(raw["commands_global"])
	m.Commands = musicCommandsFromRaw(raw["commands"], raw["blocked_commands"])
	// v7: `audio_quality` is absent in every pre-v7 doc — stamp the zod
	// default instead of trusting the zero value.
	if m.AudioQuality == "" {
		m.AudioQuality = MusicAudioQualityDefault
	}
	// v8: `auto_delete_commands` needs a PRESENCE check, not a value check.
	// An empty list is a legitimate configuration ("clean nothing"), so the
	// decoded value alone cannot tell "the admin emptied it" from "the field
	// never existed" — the trick used above for `audio_quality` (where `""` is
	// an impossible sentinel) has no equivalent here. Only the raw document
	// knows, so this is the one place the default can be seeded safely.
	if _, ok := raw["auto_delete_commands"]; !ok {
		m.AutoDeleteCommands = append([]string(nil), MusicAutoDeleteCommandsDefault...)
	}
	m.SchemaVersion = SchemaVersionMusic
	return m
}

// stripMusicCommandKeys returns a shallow copy of raw without the three keys the
// migration handles by hand (`commands`, `commands_global`, `blocked_commands`),
// so the base bson decode never trips over a legacy command shape.
func stripMusicCommandKeys(raw bson.M) bson.M {
	out := make(bson.M, len(raw))
	for k, v := range raw {
		switch k {
		case "commands", "commands_global", "blocked_commands":
			// handled via overlay / migration below
		default:
			out[k] = v
		}
	}
	return out
}

// musicCommandsFromRaw replicates the Node preprocess for `commands`:
// non-empty `blocked_commands` sets `enabled=false` on each named command
// (merging into any existing map); absent `commands` + empty blocked → the full
// default set; a present map overlays each entry onto the command default.
func musicCommandsFromRaw(commandsRaw, blockedRaw any) map[string]MusicCommand {
	commands, hasCommands := asBsonMap(commandsRaw)

	if blocked, ok := asStringSlice(blockedRaw); ok && len(blocked) > 0 {
		if !hasCommands {
			commands = bson.M{}
			hasCommands = true
		}
		for _, name := range blocked {
			entry, _ := asBsonMap(commands[name])
			if entry == nil {
				entry = bson.M{}
			}
			entry["enabled"] = false
			commands[name] = entry
		}
	}

	if !hasCommands {
		// No `commands` and no blocked list → full default set (Node's
		// `commands` zod `.default(moduleMusicMock.commands)`).
		return DefaultMusicCommands()
	}

	out := make(map[string]MusicCommand, len(commands))
	for name, entry := range commands {
		out[name] = musicCommandFromRaw(entry)
	}
	return out
}

// musicCommandFromRaw overlays a raw command entry onto the command default so
// absent leaves inherit the zod defaults (enabled=true, use_global all-true,
// access `all_except []`); a legacy boolean `use_global` expands to the
// per-axis object.
func musicCommandFromRaw(raw any) MusicCommand {
	cmd := MusicConfigurableCommandDefault()
	entry, ok := asBsonMap(raw)
	if !ok {
		return cmd
	}
	if e, ok := entry["enabled"].(bool); ok {
		cmd.Enabled = e
	}
	switch ug := entry["use_global"].(type) {
	case bool:
		cmd.UseGlobal = MusicCommandSync{Roles: ug, Channels: ug, Categories: ug}
	default:
		if ugm, ok := asBsonMap(entry["use_global"]); ok {
			if v, ok := ugm["roles"].(bool); ok {
				cmd.UseGlobal.Roles = v
			}
			if v, ok := ugm["channels"].(bool); ok {
				cmd.UseGlobal.Channels = v
			}
			if v, ok := ugm["categories"].(bool); ok {
				cmd.UseGlobal.Categories = v
			}
		}
	}
	if acc, ok := asBsonMap(entry["access"]); ok {
		cmd.Access = musicAccessFromBsonMap(acc, MusicCommandAccessDefault())
	}
	return cmd
}

// musicAccessFromRaw overlays a raw access block onto the unrestricted default
// (`all_except []` on every axis) — used for `commands_global`.
func musicAccessFromRaw(raw any) MusicCommandAccess {
	acc := MusicCommandAccessDefault()
	m, ok := asBsonMap(raw)
	if !ok {
		return acc
	}
	return musicAccessFromBsonMap(m, acc)
}

func musicAccessFromBsonMap(m bson.M, acc MusicCommandAccess) MusicCommandAccess {
	if r, ok := asBsonMap(m["roles"]); ok {
		acc.Roles = musicAccessListFromRaw(r, acc.Roles)
	}
	if c, ok := asBsonMap(m["channels"]); ok {
		acc.Channels = musicAccessListFromRaw(c, acc.Channels)
	}
	if cat, ok := asBsonMap(m["categories"]); ok {
		acc.Categories = musicAccessListFromRaw(cat, acc.Categories)
	}
	return acc
}

func musicAccessListFromRaw(m bson.M, def MusicAccessList) MusicAccessList {
	out := def
	if mode, ok := m["mode"].(string); ok {
		out.Mode = MusicAccessMode(mode)
	}
	if ids, ok := asStringSlice(m["ids"]); ok {
		out.IDs = ids
	}
	return out
}

// asBsonMap accepts the map shapes a bson.M (Mongo) or a JSON decode can
// produce for a nested object.
//
// El caso `bson.D` es el que de verdad importa: el driver de Mongo v2
// decodifica TODO sub-documento anidado dentro de un `bson.M` como `bson.D`
// (el mecanismo de "ancestor" del v1, que propagaba `bson.M` hacia abajo,
// desapareció). Sin él, `MigrateMusicRaw` no veía NI `commands` NI
// `commands_global` en un documento real —sólo en los `bson.M` que arman los
// tests unitarios a mano— y los pisaba con los defaults en cada lectura en
// frío: comandos desactivados que volvían a aparecer activos y listas de
// acceso que volvían a `all_except []`. Es exactamente el mismo fallo que ya
// se corrigió en `asModerationRawMap` (module_moderation.go).
func asBsonMap(v any) (bson.M, bool) {
	switch m := v.(type) {
	case bson.M:
		return m, true
	case map[string]any:
		return bson.M(m), true
	case bson.D:
		out := make(bson.M, len(m))
		for _, e := range m {
			out[e.Key] = e.Value
		}
		return out, true
	}
	return nil, false
}

// asStringSlice accepts the array shapes a bson.M (bson.A) or a JSON decode
// ([]any) can produce, plus a plain []string. Non-string elements are dropped.
// The bool reports whether the value was a recognised slice at all (so callers
// can tell "absent" from "present-but-empty").
func asStringSlice(v any) ([]string, bool) {
	switch arr := v.(type) {
	case []string:
		return append([]string{}, arr...), true
	case bson.A:
		out := make([]string, 0, len(arr))
		for _, e := range arr {
			if s, ok := e.(string); ok {
				out = append(out, s)
			}
		}
		return out, true
	case []any:
		out := make([]string, 0, len(arr))
		for _, e := range arr {
			if s, ok := e.(string); ok {
				out = append(out, s)
			}
		}
		return out, true
	}
	return nil, false
}

