// ModerationRawSchemaVersion lee `schema_version` de un subdoc crudo (lean) de
// `module_moderation`, tolerando las formas int/int32/int64/float64 que
// producen los decoders de BSON y de JSON. Devuelve 0 cuando falta — el repo
// trata un subdoc sin versión como "aplica los defaults completos". Espejo de
// TempvoiceRawSchemaVersion.
func ModerationRawSchemaVersion(raw bson.M) int {
	switch v := raw["schema_version"].(type) {
	case int:
		return v
	case int32:
		return int(v)

// Patch mirrors `patchModuleGreeterController`. Strict body; MergeDeepJSON
// (presence-based) semantics on the server side so partial sub-block updates
// (e.g. `welcome.message.content` only) don't clobber siblings, and explicit
// `false`/`0`/`null` leaves are applied (Node parity).
func (h *ModuleGreeterHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleGreeter]()
	ctx := c.Context()

	var body validations.UpdateModuleGreeterBody
	if err := c.Bind().Body(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	// El bind sólo comprueba la FORMA (enums, structs anidados). Los topes de
	// longitud y cardinalidad no existían en ninguna capa del servidor: este
	// endpoint acepta un PATCH directo con la credencial de api-db, y sin esto
	// un `message.content` de 1 MB se persistía y dejaba al guild sin
	// bienvenidas para siempre (Discord lo rechaza con 400 y el error sólo
	// aparece en los logs del bot).
	if verr := validations.ValidateUpdateModuleGreeter(&body); verr != nil {
		r.AddError(verr)
		return reply(c, r)
	}

	patch, err := patchMap(c.Body())
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)

	// Node applySourceAndStash(sourced{data:null}).
	if sourced != nil {
		r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	return reply(c, r)
}

// Patch mirrors `patchModuleModerationController`. Strict body
// (DisallowUnknownFields, matching the zod `.strict()`) validates the shape;
// the SAME body is then re-decoded as a raw `map[string]any` so key PRESENCE
// survives, and the repo MergeDeepJSON-merges it into the current subdoc — a
// partial PATCH preserves untouched fields, nested-block siblings, and per-key
// `commands` overrides, and explicit `false`/`0`/`null` leaves are APPLIED
// (mirrors the Node `mergeDeep`, which only skips `undefined`). An empty body
// `{}` is a no-op that still bumps schema_version + updated_at (Node returns
// 200). A missing guild → 400 MODULE_NOT_FOUND with `data:null`.
func (h *ModuleModerationHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleModeration]()
	ctx := c.Context()

	var body validations.UpdateModuleModerationBody
	dec := json.NewDecoder(bytes.NewReader(c.Body()))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	// Re-decode the (already validated) body as a raw map so key presence
	// survives — explicit false/0/null must reach the merge (Node parity).
	patch, err := patchMap(c.Body())
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	sourced, err := h.Repo.Update(ctx, c.Params("bot_id"), c.Params("guild_id"), patch)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		// Node's update-null branch stamps db + a source detail + data:null
		// before throwing MODULE_NOT_FOUND. The repo returns a bare nil here,
		// so stamp the source by hand.
		r.SetSource(result.SourceDB, sourceDetailModerationDBNotFound)
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))

