// ─── enum sets + messages (mismo estilo "Invalid option" del resto) ───────
//
// Estos son los enums que el módulo usa para DECIDIR una acción concreta
// (qué sanción aplicar, qué política seguir): a diferencia de `mode` en un
// `ModerationAccessList` (donde la cadena vacía tiene un default sensato —
// "sin restricción" — y `NormalizeModeration` la repone en silencio, ver
// `normalizeModerationAccessList` en dbguild), aquí NO hay un default
// razonable: un `action`/`policy`/`punishment` vacío o desconocido no es "no
// hacer nada de forma segura", es un estado que ninguna rama del módulo sabe
// interpretar. El zod del dashboard ya lo impedía (un <select> siempre manda
// una opción), pero un PATCH directo a la API con la credencial de api-db no
// pasa por ese formulario, así que hasta ahora podía guardar una regla con
// `action: ""` que el módulo se saltaba en silencio — parecía configurada y
// no hacía nada. Sólo se comprueba el bloque que el PATCH TRAE: un puntero
// nil sigue significando «no tocar», igual que en greeter/tts.
var (
	moderationCommandModeSet = map[dbguild.ModerationCommandMode]bool{
		dbguild.ModerationCommandModeSlash: true, dbguild.ModerationCommandModePrefix: true,
		dbguild.ModerationCommandModeBoth: true,
	}
	moderationMuteModeSet = map[dbguild.ModerationMuteMode]bool{
		dbguild.ModerationMuteModeAuto: true, dbguild.ModerationMuteModeTimeout: true,
		dbguild.ModerationMuteModeRole: true,
	}
	automodActionSet = map[dbguild.AutomodAction]bool{
		dbguild.AutomodActionDelete: true, dbguild.AutomodActionDeleteWarn: true,
		dbguild.AutomodActionDeleteTimeout: true, dbguild.AutomodActionDeleteKick: true,
		dbguild.AutomodActionDeleteBan: true,
	}
